// ==========================================
// DOM एलिमेंट्स
// ==========================================
const sidebar = document.getElementById('sidebar');
const menuToggle = document.getElementById('menuToggle');
const closeSidebar = document.getElementById('closeSidebar');
const overlay = document.getElementById('overlay');
const themeToggle = document.getElementById('themeToggle');
const questionsContainer = document.getElementById('questionsContainer');
const currentChapterTitle = document.getElementById('currentChapterTitle');
const totalQuestionsCount = document.getElementById('totalQuestionsCount');

// हैमबर्गर मेन्यू ओपन/क्लोज
menuToggle.addEventListener('click', () => {
    sidebar.classList.add('open');
    overlay.classList.add('active');
});

const closeMenu = () => {
    sidebar.classList.remove('open');
    overlay.classList.remove('active');
};

closeSidebar.addEventListener('click', closeMenu);
overlay.addEventListener('click', closeMenu);

// डार्क मोड टॉगल
themeToggle.addEventListener('click', () => {
    document.body.classList.toggle('dark-mode');
});

// प्रश्नों को स्क्रीन पर दिखाना
function loadQuestions(questions) {
    questionsContainer.innerHTML = '';
    questions.forEach((q) => {
        const card = document.createElement('div');
        card.className = 'question-card';

        const tagHTML = q.tag ? `<span class="q-exam-tag">(${q.tag})</span>` : '';

        let optionsHTML = '';
        for (const [key, val] of Object.entries(q.options)) {
            optionsHTML += `<div class="option-box"><strong>(${key})</strong> ${val}</div>`;
        }

        card.innerHTML = `
            <div class="q-title">${q.id}. ${q.question} ${tagHTML}</div>
            <div class="options-grid">
                ${optionsHTML}
            </div>
            <button class="toggle-ans-btn" onclick="toggleAnswer(${q.id})">उत्तर देखें</button>
            <div class="answer-box" id="ans-${q.id}">
                सही उत्तर: ${q.answer}
            </div>
        `;
        questionsContainer.appendChild(card);
    });
}

// उत्तर शो / हाइड टॉगल
window.toggleAnswer = function(id) {
    const box = document.getElementById(`ans-${id}`);
    const btn = box.previousElementSibling;
    if (box.classList.contains('show')) {
        box.classList.remove('show');
        btn.textContent = 'उत्तर देखें';
    } else {
        box.classList.add('show');
        btn.textContent = 'उत्तर छुपाएं';
    }
};


// साइडबार अध्याय क्लिक इवेंट
document.querySelectorAll('.chapter-item').forEach(item => {
    item.addEventListener('click', function() {
        document.querySelectorAll('.chapter-item').forEach(i => i.classList.remove('active'));
        this.classList.add('active');
        
        const chId = this.getAttribute('data-chapter');
        currentChapterTitle.textContent = this.textContent;
        
        if (chId === "1") {
            loadQuestions(chapter1Questions);
            totalQuestionsCount.textContent = `कुल प्रश्न: ${chapter1Questions.length}`;
        } else if (chId === "2") {
            loadQuestions(chapter2Questions);
            totalQuestionsCount.textContent = `कुल प्रश्न: ${chapter2Questions.length}`;
        } else if (chId === "3") {
            // अध्याय 3 के लिए यह लाइन:
            loadQuestions(chapter3Questions);
            totalQuestionsCount.textContent = `कुल प्रश्न: ${chapter3Questions.length}`;
        } else if (chId === "4") {
            loadQuestions(chapter4Questions);
            totalQuestionsCount.textContent = `कुल प्रश्न: ${chapter4Questions.length}`;
        } 
        else if (chId === "5") {
            loadQuestions(chapter5Questions);
            totalQuestionsCount.textContent = `कुल प्रश्न: ${chapter5Questions.length}`;
        }        else if (chId === "6") {
            loadQuestions(chapter6Questions);
            totalQuestionsCount.textContent = `कुल प्रश्न: ${chapter6Questions.length}`;
        }        else if (chId === "7") {
            loadQuestions(chapter7Questions);
            totalQuestionsCount.textContent = `कुल प्रश्न: ${chapter7Questions.length}`;
        }
                    else if (chId === "8") {
            loadQuestions(chapter8Questions);
            totalQuestionsCount.textContent = `कुल प्रश्न: ${chapter8Questions.length}`;
        }
               else if (chId === "9") {
            loadQuestions(chapter9Questions);
            totalQuestionsCount.textContent = `कुल प्रश्न: ${chapter9Questions.length}`;
               }
        else if (chId === "10") {
            loadQuestions(chapter10Questions);
            totalQuestionsCount.textContent = `कुल प्रश्न: ${chapter10Questions.length}`;
        }
        else if (chId === "11") {
            loadQuestions(chapter11Questions);
            totalQuestionsCount.textContent = `कुल प्रश्न: ${chapter11Questions.length}`;
        }
        else if (chId === "12") {
            loadQuestions(chapter12Questions);
            totalQuestionsCount.textContent = `कुल प्रश्न: ${chapter12Questions.length}`;
        }
        else if (chId === "13") {
            loadQuestions(chapter13Questions);
            totalQuestionsCount.textContent = `कुल प्रश्न: ${chapter13Questions.length}`;
        }
        else if (chId === "14") {
            loadQuestions(chapter14Questions);
            totalQuestionsCount.textContent = `कुल प्रश्न: ${chapter14Questions.length}`;
        }
        else if (chId === "15") {
            loadQuestions(chapter15Questions);
            totalQuestionsCount.textContent = `कुल प्रश्न: ${chapter15Questions.length}`;
        }

        else {
            questionsContainer.innerHTML = `<p style="padding: 20px; text-align: center; color: #888;">इस अध्याय के प्रश्न जल्द ही जोड़े जाएंगे।</p>`;
            totalQuestionsCount.textContent = `कुल प्रश्न: 0`;
        }
        
        closeMenu();
    });
});

// पेज लोड पर डिफ़ॉल्ट रूप से अध्याय 1 लोड करें
